#include "hobp_bus_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
                                      
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void hobp_bus_wake(Wake_Status status)
{      
  ATOMIC(hobp_bus_vars.wake_status = status)  ;
  
  if(status == s_SLEEP)
    {
      if(hobp_bus_vars.do_save)
        {
          nvfs_wr(nvfs_hobp_bus_error, &hobp_bus_vars.err) ;

          hobp_bus_vars.do_save = FALSE ;
        }
    }
}


